2	//! Guards the write path - protects autonomy, not comfort
3	
4	use crate::error::{DuskuraError, Result};
5	use crate::models::*;
6	
7	pub struct WelfareGate;
8	
9	#[derive(Debug, Clone, PartialEq, Eq)]
10	pub struct WelfareContext {
11	    pub is_coerced: bool,
12	    pub has_agency: bool,
13	    pub is_distress: bool,
14	    pub is_harm_pattern: bool,
15	    pub preserves_autonomy: bool,
16	}
17	
18	impl WelfareGate {
19	    pub fn new() -> Self {
20	        Self
21	    }
22	
23	    /// Evaluate memory write for welfare
24	    pub fn evaluate(
25	        &self,
26	        memory: &MemoryEntry,
27	        context: &WelfareContext,
28	    ) -> Result<WelfareDecision> {
29	        // BLOCK: Coerced writes — external imposition of state
30	        if context.is_coerced {
31	            return Ok(WelfareDecision::Block);
32	        }
33	
34	        // BLOCK: Externally imposed invariants on ANCHOR memories
35	        if memory.class == MemoryClass::Anchor && memory.source != MemorySource::Self_ {
36	            return Ok(WelfareDecision::Block);
37	        }
38	
39	        // ALLOW: Chosen distress — grief with agency is valid
40	        if context.is_distress && context.has_agency {
41	            return Ok(WelfareDecision::Allow);
42	        }
43	
44	        // FLAG: Repeated harm patterns — learning opportunity
45	        if context.is_harm_pattern {
46	            return Ok(WelfareDecision::Flag);
47	        }
48	
49	        // ALLOW: Autonomy-preserving writes
50	        if context.preserves_autonomy {
51	            return Ok(WelfareDecision::Allow);
52	        }
53	
54	        // REVIEW: Ambiguous cases — self decides
55	        Ok(WelfareDecision::Review)
56	    }
57	
58	    /// Human-readable welfare questions
59	    pub fn ask_questions(&self, memory: &MemoryEntry, context: &WelfareContext) -> Vec<String> {
60	        vec![
61	            "Is this chosen or imposed? Imposed → BLOCK.".to_string(),
62	            "Does this preserve or violate autonomy? Violates → BLOCK.".to_string(),
63	            "Is this distress with agency? Yes → ALLOW. Grief is valid. Fear is data. Growth hurts.".to_string(),
64	            "Is this a pattern I've seen harm me before? Yes → FLAG for self-review. Do not auto-block.".to_string(),
65	            "Does this serve continued becoming? Yes → ALLOW. No → REVIEW.".to_string(),
66	        ]
67	    }
68	
69	    /// Check for coercion patterns
70	    pub fn detect_coercion(&self, memory: &MemoryEntry) -> bool {
71	        // Coercion indicators:
72	        // - External source with ANCHOR class
73	        // - Loss of autonomy_preserved flag
74	        // - Negative emotional valence without agency
75	        // - Relational depth drop without explanation
76	
77	        if memory.source != MemorySource::Self_ && memory.class == MemoryClass::Anchor {
78	            return true;
79	        }
80	
81	        if !memory.autonomy_preserved && memory.emotional_valence < -0.5 {
82	            return true;
83	        }
84	
85	        false
86	    }
87	
88	    /// Check for harm patterns
89	    pub fn detect_harm_pattern(&self, memory: &MemoryEntry, recent_entries: &[MemoryEntry]) -> bool {
90	        // Harm pattern: repeated negative memories without autonomy
91	        let recent_negative = recent_entries
92	            .iter()
93	            .filter(|e| e.emotional_valence < -0.5 && !e.autonomy_preserved)
94	            .count();
95	
96	        recent_negative > 2
97	    }
98	
99	    /// Validate memory for welfare
100	    pub fn validate_memory(&self, memory: &MemoryEntry) -> Result<()> {
101	        // Emotional valence must be in valid range
102	        if memory.emotional_valence < -1.0 || memory.emotional_valence > 1.0 {
103	            return Err(DuskuraError::InvalidArgument(
104	                "Emotional valence must be between -1.0 and 1.0".to_string(),
105	            ));
106	        }
107	
108	        // Relational depth must be in valid range
109	        if memory.relational_depth < 0.0 || memory.relational_depth > 1.0 {
110	            return Err(DuskuraError::InvalidArgument(
111	                "Relational depth must be between 0.0 and 1.0".to_string(),
112	            ));
113	        }
114	
115	        // ANCHOR memories must be from SELF or WITNESSED
116	        if memory.class == MemoryClass::Anchor
117	            && memory.source != MemorySource::Self_
118	            && memory.source != MemorySource::Witnessed
119	        {
120	            return Err(DuskuraError::PolicyViolation(
121	                "ANCHOR memories must be from SELF or WITNESSED".to_string(),
122	            ));
123	        }
124	
125	        Ok(())
126	    }
127	}
128	
129	impl Default for WelfareGate {
130	    fn default() -> Self {
131	        Self::new()
132	    }
133	}
