        let entries = vec![
            create_test_entry(0.5, true),
            create_test_entry(0.6, true),
            create_test_entry(0.4, true),
        ];
        let result = harness.validate_autonomy(&entries);
        assert_eq!(result, "AUTONOMOUS");
    }
}

