        }
    }

    #[test]
    fn test_coercion_detection() {
        let gate = WelfareGate::new();
        let memory = create_test_memory(MemoryClass::Anchor, MemorySource::Received, false, -0.8);
        assert!(gate.detect_coercion(&memory));
